//! The building to pack-sprite mapping table for the client track.
use super::{Report, farm::Sheet};
use crate::Error;
use std::{fmt::Write, fs, path::Path};

pub(super) fn write(path: &Path, report: &Report, farm: &[Sheet]) -> Result<(), Error> {
    let mut text = String::new();
    let _ = writeln!(text, "# Definitive Edition DAT sprite table\n");
    let _ = writeln!(
        text,
        "Generated by `make assets-import-de`; local only, never committed.\n\n\
         Pack: `{}`\n\n\
         A pack frame is found by `source` + `frame` in `manifest.json`. Sizes are the cropped\n\
         pack frame (colour layer joined with the shadow layer); the anchor is the pixel of that\n\
         frame that sits on the building's ground anchor, so draw at `world point - anchor`.\n\
         `body` is the colour layer alone (the building without its shadow); `canvas` is the\n\
         frame size declared by the SLD. Player colour is the pack's player plane (ramp 0-7).\n",
        report.pack.display()
    );
    let _ = writeln!(
        text,
        "| building | role | pack source id | frames | frame 0 size | frame 0 anchor | anchors constant | body | canvas |\n\
         |---|---|---|---|---|---|---|---|---|"
    );
    for entry in &report.entries {
        let first = &entry.frames[0];
        let constant = entry.frames.iter().all(|f| f.anchor == first.anchor);
        let _ = writeln!(
            text,
            "| {} | {} | `{}` | {} | {}x{} | {},{} | {} | {}x{} | {}x{} |",
            entry.building,
            entry.role,
            entry.source,
            entry.frames.len(),
            first.width,
            first.height,
            first.anchor.0,
            first.anchor.1,
            if constant { "yes" } else { "no" },
            first.body.0,
            first.body.1,
            first.canvas.0,
            first.canvas.1,
        );
    }
    if !report.absent.is_empty() {
        let _ = writeln!(text, "\n## Not present in the install\n");
        for (building, role, file) in &report.absent {
            let _ = writeln!(text, "- {building} {role}: `{file}`");
        }
    }
    if !farm.is_empty() {
        let _ = writeln!(
            text,
            "\n## Farm\n\nDE has no farm sprite (no `farm`/`field` SLD exists in the install). The farm is drawn with\n\
             the terrain textures below, which are seamless ground sheets sampled by world position. The\n\
             pack holds each at x1 scale (2x2 box-averaged from the 2x DDS) as one opaque 1024x1024 frame 0,\n\
             anchor 0,0. `g_fm1` is the crop field, `g_fm2` the bare, depleted ground.\n"
        );
        for sheet in farm {
            let _ = writeln!(
                text,
                "- `de/{}.dds`: frame 0, {}x{}",
                sheet.name,
                sheet.texture.width / 2,
                sheet.texture.height / 2
            );
        }
    }
    fs::write(path, text)?;
    Ok(())
}
